; align-items: center; gap: 11px; font-family: var(--numbers); font-size: 39px; font-weight: 500; line-height: 1.2; margin-top: 4px; }.pot-chip { display: inline-block; width: 22px; height: 22px; border: 4px dashed #dac78f; border-radius: 50%; outline: 1px solid #dac78f; }.community-cards { display: flex; gap: 10px; margin: 19px 0 17px; }.community-cards :deep(.playing-card) { width: 77px; height: 108px; }.street-label { display: flex; align-items: center; gap: 12px; color: #aec3a1; font-size: 11px; }.street-label>span { color: #d2dfc0; border-right: 1px solid #9daf8344; padding-right: 12px; }.stage-caption { max-width: 1420px; margin: auto; padding: 6px 12px 19px; display: flex; justify-content: space-between; font-size: 8px; color: #788b73; }.player-seat { position: absolute; left: clamp(54px, var(--seat-x), calc(100% - 54px)); top: var(--seat-y); transform: translate(-50%, -50%); width: 126px; display: flex; flex-direction: column; align-items: center; z-index: 2; }.avatar { width: 47px; height: 47px; border-radius: 50%; display: grid; place-items: center; font-size: 18px; font-weight: 550; position: relative; border: 3px solid #1d2c26; box-shadow: 0 2px 7px #0003; }.avatar-0 { background: #d6e8d1; color: #537247; }.avatar-1 { background: #eccfd4; color: #a45e6a; }.avatar-2 { background: #d0e2f0; color: #5b809a; }.avatar-3 { background: #eddfb7; color: #9d864d; }.seat-details { margin-top: 3px; min-width: 83px; max-width: 134px; padding: 5px 10px; text-align: center; background: #1d3027; border: 1px solid #42533a; border-radius: 5px; }.seat-name { color: #e5eddd; font-size: 12px; display: block; overflow-wrap: anywhere; }.seat-name small { font-size: 9px; color: #9fb78c; margin-left: 4px; }.seat-chips { display: block; font-size: 15px; font-family: var(--numbers); font-weight: 500; color: #d5e0bd; margin-top: 4px; }.seat-active .avatar { outline: 2px solid #e2c47b; box-shadow: 0 0 0 6px #e2c47b18; }.seat-active .seat-details { border-color: #bba367; }.seat-active .seat-chips { color: #f3d796; }.seat-winner .avatar { background: #e4ca8b; color: #7e5f25; outline: 2px solid #c9ae64; }.seat-folded { opacity: .4; }.dealer-badge { position: absolute; top: 4px; right: 23px; background: #eee8d5; width: 19px; height: 19px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 650; z-index: 3; color: #796a40; box-shadow: 0 2px 3px #0004; }.online-dot { position: absolute; bottom: -1px; right: -1px; width: 9px; height: 9px; border: 2px solid #1d2c26; background: #a7aaa0; border-radius: 50%; }.online-dot.online { background: #88bc70; }.seat-cards { position: absolute; display: flex; gap: 4px; top: -46px; }.seat-upper .seat-cards { top: 100%; margin-top: 4px; }.seat-action { font-size: 10px; padding: 3px 9px; margin-top: 4px; border-radius: 3px; font-weight: 500; }.tone-call { background: #ead095; color: #685020; }.tone-check { background: #cce6e5; color: #39727b; }.tone-raise { background: #6389c3; color: #fff; }.tone-all-in { background: #c45b59; color: #fff4df; }.tone-fold { background: #8a9480; color: #e4eadc; }.move-feedback { position: absolute; left: 50%; top: 72%; transform: translate(-50%, -50%); display: flex; align-items: center; gap: 11px; padding: 11px 19px; border-radius: 6px; box-shadow: 0 6px 14px #07170e44; z-index: 4; min-width: 150px; max-width: 80%; pointer-events: none; }.move-feedback small { display: block; font-size: 9px; opacity: .75; max-width: 130px; overflow-wrap: anywhere; }.move-feedback b { display: block; font-size: 18px; margin-top: 2px; }.move-feedback strong { font-family: var(--numbers); font-size: 22px; font-weight: 550; margin-left: 7px; }.move-enter-active,.move-leave-active { transition: opacity .2s, transform .2s; }.move-enter-from,.move-leave-to { opacity: 0; transform: translate(-50%, -35%); }.action-dock { background: #fff; border-top: 3px solid #e4e9dd; padding: 25px 4% 30px; }.action-dock.is-your-turn { border-top-color: #dbbe78; }.dock-inner { max-width: 1420px; margin: auto; display: grid; grid-template-columns: minmax(310px, .8fr) minmax(0, 1.7fr); align-items: center; gap: 45px; }.own-hand { display: flex; align-items: center; gap: 18px; }.own-cards { display: flex; gap: 5px; }.own-cards :deep(.playing-card) { width: 57px; height: 81px; }.hand-details { flex-shrink: 0; }.eyebrow { font-size: 8px; color: #98a58b; font-weight: 600; }.hand-details h2 { font-size: 16px; font-weight: 550; margin: 6px 0 12px; }.hand-toggle { display: flex; align-items: center; gap: 5px; border: 0; padding: 0; background: none; font-size: 10px; color: #7f986b; }.my-stack { margin-left: auto; padding-left: 15px; text-align: right; }.my-stack span { font-size: 9px; color: #9caa8b; }.my-stack b { display: block; font-family: var(--numbers); font-size: 23px; font-weight: 500; color: #577342; margin-top: 6px; }.settlement { max-width: 1050px; margin: auto; padding: 28px 4% 35px; }.settlement-heading { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 20px; }.settlement-heading h2 { display: flex; align-items: center; gap: 9px; font-size: 21px; font-weight: 550; margin: 8px 0 0; }.settlement-heading h2 svg { color: #b29855; }.standings { display: grid; grid-template-columns: 1fr 1fr; gap: 0 35px; }.standing-row { display: grid; grid-template-columns: 20px minmax(65px, 1fr) auto 65px 48px; align-items: center; gap: 10px; padding: 12px 0; border-bottom: 1px solid #e7eddd; min-height: 72px; }.rank-number { font-size: 12px; color: #a69460; }.standing-row>b { font-size: 12px; font-weight: 500; overflow-wrap: anywhere; }.standing-row small { font-size: 9px; color: #9aaa86; }.standing-row>strong { text-align: right; font-family: var(--numbers); font-weight: 500; font-size: 17px; }.standing-row>span:last-child { text-align: right; font-size: 11px; }.ranking-hand { display: flex; gap: 3px; }.profit { color: #70955b; }.loss { color: #bc7b6e; }.finish-note { display: flex; align-items: center; justify-content: center; gap: 7px; color: #92a47e; font-size: 11px; margin: 25px 0 0; }.waiting-next { font-size: 12px; color: #91a47e; }
