@media(max-width:600px) { .table-topline { height: 39px; padding: 0 16px; }.table-identity { gap: 6px; font-size: 10px; }.table-identity i { margin: 0 2px; }.blind-info { font-size: 9px; }.round-count { font-size: 9px; }.round-count b { font-size: 15px; }.round-count>span { font-size: 9px; }.poker-scene { height: 395px; }.table-rim { inset: 58px 2px 45px; padding: 10px; border-radius: 44%; }.felt-outline { inset: 12px; }.table-stage { padding: 0 10px; }.player-seat { left: clamp(44px, var(--seat-x), calc(100% - 44px)); width: 90px; }.avatar { width: 35px; height: 35px; font-size: 13px; border-width: 2px; }.seat-details { min-width: 65px; max-width: 94px; padding: 4px 6px; }.seat-name { font-size: 10px; }.seat-name small { font-size: 8px; margin-left: 3px; }.seat-chips { font-size: 12px; margin-top: 3px; }.seat-action { font-size: 9px; padding: 2px 6px; margin-top: 3px; }.seat-cards { display: none; }.dealer-badge { width: 16px; height: 16px; font-size: 8px; right: 14px; top: 2px; }.felt-wordmark { font-size: 7px; margin-bottom: 12px; }.felt-wordmark svg { width: 11px; }.pot-label { font-size: 9px; }.pot-amount { font-size: 29px; gap: 8px; }.pot-chip { width: 16px; height: 16px; border-width: 3px; }.community-cards { gap: 5px; margin: 14px 0 12px; }.community-cards :deep(.playing-card) { width: min(41px, calc((100vw - 180px) / 5)); height: 61px; }.community-cards :deep(.corner) { font-size: 13px; left: 4px; top: 4px; }.community-cards :deep(.corner span) { font-size: 10px; }.community-cards :deep(.bottom) { top: auto; left: auto; bottom: 4px; right: 4px; }.community-cards :deep(.center-suit) { font-size: 22px; }.street-label { font-size: 9px; gap: 7px; }.street-label>span { padding-right: 7px; }.stage-caption { padding: 1px 8px 12px; font-size: 6px; }.move-feedback { top: 75%; padding: 8px 13px; gap: 8px; min-width: 125px; }.move-feedback b { font-size: 15px; }.move-feedback small { font-size: 8px; }.move-feedback strong { font-size: 18px; }.move-feedback>svg { width: 17px; }.action-dock { padding: 15px 16px 24px; }.dock-inner { gap: 16px; }.own-hand { gap: 11px; }.my-stack b { font-size: 22px; }.my-stack span { font-size: 9px; }.own-cards :deep(.playing-card) { width: 39px; height: 56px; }.own-cards :deep(.corner) { font-size: 12px; left: 4px; top: 4px; }.own-cards :deep(.corner span) { font-size: 9px; }.own-cards :deep(.bottom) { top: auto; left: auto; bottom: 4px; right: 4px; }.own-cards :deep(.center-suit) { font-size: 22px; }.settlement { padding: 20px 19px 30px; }.settlement-heading { gap: 10px; margin-bottom: 15px; }.settlement-heading h2 { font-size: 17px; }.settlement-heading>.button { font-size: 11px; padding: 0 11px; height: 41px; }.standing-row { gap: 8px; grid-template-columns: 17px minmax(60px, 1fr) auto 55px 42px; }.standing-row>b { font-size: 11px; }.standing-row>strong { font-size: 15px; }.standing-row>span:last-child { font-size: 10px; } }
